169	/*! Borrowed Single Queue Index Threads
170	 *
171	 *  Adapts an existing thread pool to IndexThreads. The caller must keep the
172	 *  pool alive for the lifetime of this object.
173	 */
174	class BorrowedSingleQueueIndexThreads : public IndexThreads {
175	 public:
176	  //! Constructor
177	  explicit BorrowedSingleQueueIndexThreads(ailego::ThreadPool &pool)
178	      : pool_(pool) {}
179	
180	  //! Destructor
181	  ~BorrowedSingleQueueIndexThreads() override = default;
182	
183	  //! Retrieve thread count in pool
184	  size_t count() const override {
185	    return pool_.count();
186	  }
187	
188	  //! Stop all threads
189	  void stop() override {
190	    pool_.stop();
191	  }
192	
193	  //! Submit a task to be executed asynchronous
194	  void submit(ailego::ClosureHandler &&task) override {
195	    while (pool_.pending_count() >= kMaxQueueSize) {
196	      std::this_thread::sleep_for(std::chrono::milliseconds(1));
197	    }
198	    pool_.enqueue_and_wake(std::move(task));
199	  }
200	
201	  //! Make a task group
202	  TaskGroup::Pointer make_group() override {
203	    return std::make_shared<SingleQueueIndexThreads::SingleQueueTaskGroup>(
204	        pool_.make_group());
205	  }
206	
207	  //! Get the current work thread index
208	  int indexof_this() const override {
209	    return pool_.indexof_this();
210	  }
211	
212	 public:
213	  //! Disable them
214	  BorrowedSingleQueueIndexThreads(const BorrowedSingleQueueIndexThreads &) =
215	      delete;
216	  BorrowedSingleQueueIndexThreads(BorrowedSingleQueueIndexThreads &&) = delete;
217	  BorrowedSingleQueueIndexThreads &operator=(
218	      const BorrowedSingleQueueIndexThreads &) = delete;
219	
