697	int DiskAnnBuilder::build(IndexThreads::Pointer threads,
698	                          IndexHolder::Pointer holder) {
699	  if (state_ != BUILD_STATE_TRAINED) {
700	    LOG_ERROR("Train the builder before DiskAnnBuilder::build");
701	    return IndexError_NoReady;
702	  }
703	  if (!holder) {
704	    LOG_ERROR("Invalid holder for DiskAnnBuilder::build");
705	    return IndexError_InvalidArgument;
706	  }
707	
708	  LOG_INFO("Start DiskAnnBuilder::build");
709	
710	  auto start_time = ailego::Monotime::MilliSeconds();
711	
712	  holder_ = holder;
713	
714	  if (!threads) {
715	    threads =
716	        std::make_shared<SingleQueueIndexThreads>(build_thread_count_, false);
717	    if (!threads) {
718	      return IndexError_NoMemory;
719	    }
720	  }
721	
722	  auto iter = holder->create_iterator();
723	  if (!iter) {
724	    LOG_ERROR("Create iterator for holder failed");
725	    return IndexError_Runtime;
726	  }
727	
728	  if (!holder->is_matched(raw_meta_) || !holder->multipass() ||
729	      holder->count() > std::numeric_limits<uint32_t>::max()) {
730	    return IndexError_Mismatch;
731	  }
732	  if (ailego_unlikely(holder->count() == 0)) {
733	    LOG_ERROR("Holder is empty");
734	    return IndexError_Runtime;
735	  }
736	
737	  int ret = entity_.reserve_space(holder->count());
738	  if (ret != 0) return ret;
739	
740	  error_ = false;
741	  while (iter->is_valid()) {
742	    if (entity_.doc_cnt() >= holder->count()) return IndexError_Mismatch;
743	    ret = entity_.add_vector(iter->key(), iter->data());
744	    if (ailego_unlikely(ret != 0)) {
745	      return ret;
746	    }
747	
748	    iter->next();
749	  }
750	
751	  if (entity_.doc_cnt() != holder->count()) return IndexError_Mismatch;
752	  iter.reset();
753	  LOG_INFO("Finished saving vector");
754	
755	  LOG_INFO("Start to calculate entrypoint");
756	  ret = calculate_entry_point();
757	  if (ailego_unlikely(ret != 0)) {
758	    return ret;
759	  }
760	
761	  LOG_INFO("Start to build vamana graph");
762	  ret = build_internal(threads);
763	  if (ret != 0) {
764	    return ret;
765	  }
766	
767	  LOG_INFO("Start final cleanup..");
768	  ret = prune_internal(threads);
769	  if (ret != 0) {
770	    return ret;
771	  }
772	
